<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {request} from './service';import {useUserStoreHook} from '@/store/modules/user';import LinIcon from './LinIcon.vue';import GitCalendar from './GitCalendar.vue';
const me=useUserStoreHook(),posts=ref([]),pending=ref(0),applications=ref(0),moments=ref([]),albums=ref([]),seed=ref(0),note=ref(localStorage.getItem('lin-studio-note-'+me.id)||'');const ideas=['最近一部作品，留下了什么？','记录一个今天解决的小问题。','如果给这个星期起个标题……','分享一个反复回访的游戏世界。','把今天喜欢的三个瞬间写下来。'];const published=computed(()=>posts.value.filter(p=>p.status==='published').length),drafts=computed(()=>posts.value.filter(p=>p.status==='draft'));
onMounted(async()=>{posts.value=await request('/api/studio/posts');moments.value=await request('/api/studio/journal/moments');albums.value=await request('/api/studio/journal/albums');if(me.role===1){pending.value=(await request('/api/admin/comments')).length;applications.value=(await request('/api/admin/registrations')).length;}});
function saveNote(){localStorage.setItem('lin-studio-note-'+me.id,note.value);}
const shortcuts=[['pen','写篇文章','让想法长成一篇文章','/article/addArticle'],['chat','发条说说','记录此刻，不必长篇','/moments'],['image','整理相册','为喜欢的瞬间留位置','/albums']];
</script>
<template><div class="studio-dashboard"><section class="studio-welcome"><div><span class="studio-eyebrow">YOUR CREATIVE SPACE</span><h1>嗨，{{me.nick_name||'Lin'}} <span>✦</span><br/>今天，想留下点什么？</h1><p>不必等到万事俱备。一个念头，就能开启新的一页。</p><RouterLink to="/article/addArticle" class="studio-primary"><LinIcon name="pen" :size="18"/>开始写作 <span>↗</span></RouterLink></div><div class="welcome-art"><span class="art-orbit"/><div class="art-paper"><small>NOTE TO SELF</small><strong>Make room<br/>for the things<br/><i>you love.</i></strong><span>— Lin’s notebook</span></div><div class="art-spark">✳</div><span class="art-label">灵感正在发生</span></div></section><div class="studio-metrics"><div><span>已发布文章 <LinIcon name="book" :size="18"/></span><b>{{published}}<small>篇</small></b><p>{{drafts.length}} 篇草稿，等待继续</p></div><div><span>生活切片 <LinIcon name="chat" :size="18"/></span><b>{{moments.length}}<small>条说说</small></b><p>碎碎念也有自己的价值</p></div><div><span>{{me.role===1?'待审核评论':'光影收藏'}} <LinIcon name="heart" :size="18"/></span><b>{{me.role===1?pending:albums.length}}<small>{{me.role===1?'条':'本相册'}}</small></b><p>{{me.role===1?'你通过之后，留言才会公开':'用照片收藏走过的日常'}}</p><RouterLink v-if="me.role===1" to="/registrations" class="application-count">{{applications}} 份注册申请等待你处理 ↗</RouterLink></div></div><div class="studio-shortcuts"><RouterLink v-for="[icon,title,sub,url] in shortcuts" :key="url" :to="url"><span class="shortcut-icon"><LinIcon :name="icon" :size="22"/></span><div><h3>{{title}}</h3><p>{{sub}}</p></div><span>↗</span></RouterLink></div><div class="studio-columns"><section class="studio-panel"><header><h2>继续上次的灵感</h2><RouterLink to="/article/articleList">全部文章 ↗</RouterLink></header><el-empty v-if="!posts.length" description="从第一篇随手记开始吧" :image-size="75"/><RouterLink v-for="p in posts.slice(0,5)" :key="p.id" :to="'/article/editArticle?articleId='+p.id" class="recent-post"><span class="recent-icon"><LinIcon name="book" :size="18"/></span><div><strong>{{p.title}}</strong><small>{{p.category}} · {{p.updated.slice(0,10)}}</small></div><span class="post-state" :class="p.status">{{({published:'已发布',draft:'草稿',private:'私密',scheduled:'定时'})[p.status]}}</span></RouterLink></section><section class="studio-panel idea-panel"><span class="studio-eyebrow">A LITTLE INSPIRATION</span><h2>卡住的时候，<br/>换个角度看看。</h2><p class="idea-prompt">{{ideas[seed]}}</p><div class="idea-actions"><button @click="seed=(seed+1)%ideas.length">↻ 换个灵感</button><RouterLink :to="'/article/addArticle?prompt='+encodeURIComponent(ideas[seed])">就写这个 ↗</RouterLink></div><textarea v-model="note" placeholder="这里放一张临时便签……" @input="saveNote"/><small>便签只保存在当前设备</small></section></div><section class="life-doors"><a href="/workspace/tasks"><span>01 / PLAN</span><h3>把今天安排好 ↗</h3><p>任务、日历与专注计时</p></a><a href="/workspace/library"><span>02 / LOVE</span><h3>回到喜欢的故事 ↗</h3><p>番剧、游戏与自己的收藏</p></a><a href="/workspace/review"><span>03 / REMEMBER</span><h3>给日常一个后日谈 ↗</h3><p>只属于自己的生活存档</p></a></section><GitCalendar/></div></template>
